from pathlib import Path
import os
root=Path(os.environ.get('GRADLE_DIR','source-5.10.4/PME-Quebec-5.10-Native-Wyze-Source'))
java=root/'app/src/main/java/com/pmequebec/app/MainActivity.java'
manifest=root/'app/src/main/AndroidManifest.xml'
html=root/'app/src/main/assets/index.html'

# Android permissions
m=manifest.read_text(encoding='utf-8')
perms=['android.permission.ACCESS_WIFI_STATE','android.permission.CHANGE_WIFI_STATE','android.permission.BLUETOOTH_SCAN','android.permission.BLUETOOTH_CONNECT','android.permission.NEARBY_WIFI_DEVICES','android.permission.POST_NOTIFICATIONS']
anchor='<uses-permission android:name="android.permission.INTERNET" />'
for perm in perms:
    tag=f'<uses-permission android:name="{perm}" />'
    if tag not in m:
        if anchor in m: m=m.replace(anchor,anchor+'\n    '+tag,1)
        else: m=m.replace('<application','    '+tag+'\n\n    <application',1)
manifest.write_text(m,encoding='utf-8')

# Native bridge
s=java.read_text(encoding='utf-8')
if 'PME_NETWORK_BRIDGE_7000' not in s:
    s=s.replace('import android.content.Intent;','import android.content.Intent;\nimport android.content.Context;\nimport android.os.Build;\nimport android.provider.Settings;\nimport android.net.wifi.WifiManager;\nimport android.net.wifi.WifiInfo;\nimport android.bluetooth.BluetoothAdapter;\nimport android.bluetooth.BluetoothDevice;\nimport android.bluetooth.BluetoothManager;\nimport java.net.NetworkInterface;\nimport java.net.InetAddress;\nimport java.util.Collections;\nimport java.util.Set;',1)
    # expand initial permission request created by previous patch
    old='''        if (checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) != PackageManager.PERMISSION_GRANTED) needed.add(Manifest.permission.ACCESS_COARSE_LOCATION);\n        if (!needed.isEmpty()) requestPermissions(needed.toArray(new String[0]), REQ_INITIAL);'''
    new='''        if (checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) != PackageManager.PERMISSION_GRANTED) needed.add(Manifest.permission.ACCESS_COARSE_LOCATION);\n        if (Build.VERSION.SDK_INT >= 31) {\n            if (checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN) != PackageManager.PERMISSION_GRANTED) needed.add(Manifest.permission.BLUETOOTH_SCAN);\n            if (checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) != PackageManager.PERMISSION_GRANTED) needed.add(Manifest.permission.BLUETOOTH_CONNECT);\n        }\n        if (Build.VERSION.SDK_INT >= 33) {\n            if (checkSelfPermission(Manifest.permission.NEARBY_WIFI_DEVICES) != PackageManager.PERMISSION_GRANTED) needed.add(Manifest.permission.NEARBY_WIFI_DEVICES);\n            if (checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) needed.add(Manifest.permission.POST_NOTIFICATIONS);\n        }\n        if (!needed.isEmpty()) requestPermissions(needed.toArray(new String[0]), REQ_INITIAL);'''
    if old in s: s=s.replace(old,new,1)
    s=s.replace('webView.addJavascriptInterface(new WyzeBridge(), "WyzeNative");','webView.addJavascriptInterface(new WyzeBridge(), "WyzeNative");\n        webView.addJavascriptInterface(new NetworkBridge(), "PMENetwork");',1)
    insert='''\n    // PME_NETWORK_BRIDGE_7000 — network visibility is best-effort and only reports data Android exposes.\n    public class NetworkBridge {\n        @JavascriptInterface public void requestRequiredPermissions() { runOnUiThread(() -> requestInitialPermissions()); }\n        @JavascriptInterface public void openAppSettings() {\n            runOnUiThread(() -> {\n                try { Intent i=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS, Uri.parse("package:"+getPackageName())); startActivity(i); } catch(Exception ignored) {}\n            });\n        }\n        @JavascriptInterface public String permissionStatus() {\n            try {\n                JSONObject o=new JSONObject();\n                o.put("camera", Build.VERSION.SDK_INT<23 || checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED);\n                o.put("location", Build.VERSION.SDK_INT<23 || checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED || checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED);\n                o.put("bluetooth", Build.VERSION.SDK_INT<31 || (checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)==PackageManager.PERMISSION_GRANTED && checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED));\n                o.put("nearbyWifi", Build.VERSION.SDK_INT<33 || checkSelfPermission(Manifest.permission.NEARBY_WIFI_DEVICES)==PackageManager.PERMISSION_GRANTED);\n                o.put("notifications", Build.VERSION.SDK_INT<33 || checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED);\n                return o.toString();\n            } catch(Exception e){ return jsonError(e); }\n        }\n        @JavascriptInterface public String snapshot() {\n            JSONArray devices=new JSONArray(); JSONObject root=new JSONObject();\n            try {\n                root.put("permissions",new JSONObject(permissionStatus()));\n                WifiManager wm=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);\n                if(wm!=null){\n                    WifiInfo wi=wm.getConnectionInfo();\n                    JSONObject net=new JSONObject(); net.put("kind","Wi-Fi"); net.put("name",cleanWifi(wi==null?"":wi.getSSID()));\n                    net.put("id",wi==null?"":String.valueOf(wi.getBSSID())); net.put("signal",wi==null?0:wi.getRssi()); net.put("state","connecté"); devices.put(net);\n                }\n                try {\n                    for(NetworkInterface ni: Collections.list(NetworkInterface.getNetworkInterfaces())) {\n                        for(InetAddress a: Collections.list(ni.getInetAddresses())) {\n                            if(a.isLoopbackAddress()) continue; JSONObject d=new JSONObject(); d.put("kind","Interface réseau"); d.put("name",ni.getDisplayName()); d.put("id",ni.getName()); d.put("ip",a.getHostAddress()); d.put("state",ni.isUp()?"active":"inactive"); devices.put(d);\n                        }\n                    }\n                } catch(Exception ignored){}\n                try {\n                    BluetoothManager bm=(BluetoothManager)getSystemService(Context.BLUETOOTH_SERVICE); BluetoothAdapter ba=bm==null?null:bm.getAdapter();\n                    if(ba!=null && (Build.VERSION.SDK_INT<31 || checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED)) {\n                        Set<BluetoothDevice> bonded=ba.getBondedDevices();\n                        if(bonded!=null) for(BluetoothDevice bd: bonded){ JSONObject d=new JSONObject(); d.put("kind","Bluetooth"); d.put("name",bd.getName()==null?"Appareil Bluetooth":bd.getName()); d.put("id",bd.getAddress()); d.put("state","jumelé"); devices.put(d); }\n                    }\n                } catch(Exception ignored){}\n                // Some Android versions expose recently learned LAN peers here; failure is expected on restricted devices.\n                try (BufferedReader r=new BufferedReader(new FileReader("/proc/net/arp"))) {\n                    String line; boolean first=true; while((line=r.readLine())!=null){ if(first){first=false;continue;} String[] p=line.trim().split("\\\\s+"); if(p.length>=4 && !"00:00:00:00:00:00".equals(p[3])){ JSONObject d=new JSONObject(); d.put("kind","LAN"); d.put("name","Appareil réseau"); d.put("ip",p[0]); d.put("id",p[3]); d.put("state","détecté"); devices.put(d); } }\n                } catch(Exception ignored){}\n                root.put("devices",devices); root.put("scannedAt",System.currentTimeMillis()); root.put("note","Android peut masquer certaines adresses MAC et certains appareils non jumelés."); return root.toString();\n            } catch(Exception e){ return jsonError(e); }\n        }\n        private String cleanWifi(String v){ if(v==null)return ""; return v.replace("\\\"",""); }\n    }\n'''
    s=s.replace('\n    @Override protected void onDestroy() {',insert+'\n    @Override protected void onDestroy() {',1)
java.write_text(s,encoding='utf-8')

# Security UI
h=html.read_text(encoding='utf-8')
if 'pme-network-security-7000' not in h:
    style='''\n<style id="pme-network-security-7000">\n#pmeNetworkSecurity{margin-top:16px;background:linear-gradient(180deg,#07152d,#030914)!important;border:1px solid #0b6cff!important;border-radius:18px;padding:14px;box-shadow:0 0 24px rgba(0,119,255,.18)}\n#pmeNetworkSecurity .net-actions{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}#pmeNetworkSecurity button{background:linear-gradient(180deg,#0c66ff,#00379d)!important;color:#fff!important;border:1px solid #3ca0ff!important}\n#pmeNetworkSecurity table{width:100%;border-collapse:collapse;font-size:12px}#pmeNetworkSecurity th,#pmeNetworkSecurity td{padding:8px 6px;border-bottom:1px solid #17345f;text-align:left;overflow-wrap:anywhere}#pmeNetworkSecurity th{color:#8fc5ff}#pmeNetPerms{font-size:12px;color:#b8d7ff}.net-ok{color:#70ffb0}.net-no{color:#ff9b9b}\n</style>\n'''
    script='''\n<script id="pme-network-security-runtime-7000">\n(function(){'use strict';\nasync function uid(){try{var sb=typeof cloudClient==='function'?cloudClient():null;if(sb){var r=await sb.auth.getSession();var id=r&&r.data&&r.data.session&&r.data.session.user&&r.data.session.user.id;if(id)return id}}catch(e){}return 'local-user'}\nasync function key(){return 'pme-network-inventory-v1:'+(await uid())}\nfunction esc(v){return String(v==null?'':v).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]})}\nfunction ensure(){var sec=document.getElementById('securityAuthorizedContent')||document.getElementById('securitySection');if(!sec||document.getElementById('pmeNetworkSecurity'))return;var p=document.createElement('section');p.id='pmeNetworkSecurity';p.innerHTML='<h3>📡 Réseaux et appareils</h3><p class="muted">Détection locale Wi-Fi/LAN, interfaces réseau et appareils Bluetooth accessibles à Android. Les appareils peuvent être renommés et sont mémorisés séparément pour chaque utilisateur.</p><div id="pmeNetPerms"></div><div class="net-actions"><button id="pmeNetPermBtn" type="button">🔐 Autorisations requises</button><button id="pmeNetScanBtn" type="button">📡 Scanner maintenant</button><button id="pmeNetSettingsBtn" type="button">⚙️ Paramètres Android</button></div><div style="overflow:auto"><table><thead><tr><th>Type</th><th>Nom</th><th>IP / identifiant</th><th>État</th><th>Signal</th></tr></thead><tbody id="pmeNetRows"></tbody></table></div><p id="pmeNetNote" class="muted"></p>';sec.appendChild(p);p.querySelector('#pmeNetPermBtn').onclick=function(){try{PMENetwork.requestRequiredPermissions()}catch(e){}};p.querySelector('#pmeNetSettingsBtn').onclick=function(){try{PMENetwork.openAppSettings()}catch(e){}};p.querySelector('#pmeNetScanBtn').onclick=scan;status();scan()}\nfunction status(){var e=document.getElementById('pmeNetPerms');if(!e)return;try{var p=JSON.parse(PMENetwork.permissionStatus());var labels={camera:'Caméra',location:'Localisation',bluetooth:'Bluetooth',nearbyWifi:'Wi-Fi à proximité',notifications:'Notifications'};e.innerHTML=Object.keys(labels).map(function(k){return '<span class="'+(p[k]?'net-ok':'net-no')+'">'+labels[k]+': '+(p[k]?'✓':'à autoriser')+'</span>'}).join(' · ')}catch(x){e.textContent='Pont Android indisponible.'}}\nasync function scan(){var rows=document.getElementById('pmeNetRows');if(!rows)return;rows.innerHTML='<tr><td colspan="5">Analyse…</td></tr>';try{var raw=PMENetwork.snapshot();var data=JSON.parse(raw),k=await key(),saved=JSON.parse(localStorage.getItem(k)||'{}'),seen=saved.devices||{};(data.devices||[]).forEach(function(d){var id=d.id||d.ip||d.name||Math.random().toString(36);var old=seen[id]||{};seen[id]=Object.assign({},old,d,{firstSeen:old.firstSeen||Date.now(),lastSeen:Date.now()})});localStorage.setItem(k,JSON.stringify({devices:seen,updatedAt:Date.now()}));var list=Object.keys(seen).map(function(id){return seen[id]});rows.innerHTML=list.map(function(d){return '<tr><td>'+esc(d.kind)+'</td><td contenteditable="true" data-net-id="'+esc(d.id||d.ip||'')+'">'+esc(d.customName||d.name||'Inconnu')+'</td><td>'+esc(d.ip||d.id||'—')+'</td><td>'+esc(d.state||'détecté')+'</td><td>'+esc(d.signal||'—')+'</td></tr>'}).join('')||'<tr><td colspan="5">Aucun appareil détecté.</td></tr>';rows.querySelectorAll('[data-net-id]').forEach(function(c){c.onblur=async function(){var k=await key(),o=JSON.parse(localStorage.getItem(k)||'{}'),id=c.dataset.netId;if(o.devices&&o.devices[id]){o.devices[id].customName=c.textContent.trim();localStorage.setItem(k,JSON.stringify(o))}}});document.getElementById('pmeNetNote').textContent=data.note||'';status()}catch(e){rows.innerHTML='<tr><td colspan="5">Détection indisponible : '+esc(e.message||e)+'</td></tr>';status()}}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ensure);else ensure();new MutationObserver(ensure).observe(document.documentElement,{childList:true,subtree:true});window.PMENetworkScan=scan;})();\n</script>\n'''
    pos=h.lower().rfind('</head>'); h=h[:pos]+style+h[pos:]
    pos=h.lower().rfind('</body>'); h=h[:pos]+script+h[pos:]
html.write_text(h,encoding='utf-8')
print('Sécurité réseau + permissions Android intégrées')
